#!/usr/bin/env python3
from __future__ import annotations
import argparse, hashlib, json
from pathlib import Path


def convert(src: Path, dst: Path) -> dict:
    raw=src.read_text()
    tokens=iter(raw.split())
    magic=next(tokens)
    if magic!='QEC_CUBIC_V2': raise ValueError(magic)
    orbit_count=int(next(tokens)); period=int(next(tokens)); detectors=int(next(tokens)); logicals=int(next(tokens)); denominator=int(next(tokens)); detector_blocks=int(next(tokens))
    gauge_masks=[next(tokens) for _ in range(logicals)]
    n_locations=orbit_count*period
    out=[f'{n_locations} {detectors} {logicals} {orbit_count}']
    nonzero_effects=0; zero_effect_outcomes=0; total_outcomes=0
    for expected in range(n_locations):
        index=int(next(tokens)); count=int(next(tokens))
        if index!=expected: raise ValueError((expected,index))
        effects=[]
        for _ in range(count):
            effect=int(next(tokens),16); rate=int(next(tokens))
            if rate<=0: raise ValueError('nonpositive rate')
            total_outcomes+=1
            if effect==0: zero_effect_outcomes+=1
            else: effects.append(effect)
        effects=sorted(set(effects)); nonzero_effects+=len(effects)
        out.append(str(len(effects)) + ('' if not effects else ' ' + ' '.join(format(e,'x') for e in effects)))
    try:
        extra=next(tokens)
    except StopIteration:
        extra=None
    if extra is not None: raise ValueError(f'trailing token {extra}')
    reps=[orbit*period for orbit in range(orbit_count)]
    out.append(' '.join(map(str,reps)))
    text='\n'.join(out)+'\n'
    dst.parent.mkdir(parents=True,exist_ok=True); dst.write_text(text)
    return {
        'source':str(src),'destination':str(dst),'source_sha256':hashlib.sha256(raw.encode()).hexdigest(),
        'destination_sha256':hashlib.sha256(text.encode()).hexdigest(),'locations':n_locations,
        'detectors':detectors,'logicals':logicals,'translation_orbits':orbit_count,'period':period,
        'rate_denominator':denominator,'detector_blocks':detector_blocks,'gauge_masks_hex':gauge_masks,
        'merged_fault_outcomes':total_outcomes,'zero_effect_fault_outcomes_omitted':zero_effect_outcomes,
        'nonzero_effects_exported':nonzero_effects,'representatives':reps,
    }


def main():
    ap=argparse.ArgumentParser(); ap.add_argument('source',type=Path); ap.add_argument('destination',type=Path); ap.add_argument('--metadata',type=Path)
    a=ap.parse_args(); result=convert(a.source,a.destination)
    if a.metadata:
        a.metadata.write_text(json.dumps(result,indent=2,sort_keys=True)+'\n')
    print(json.dumps(result,indent=2,sort_keys=True))
if __name__=='__main__': main()

