=== h170 stability verify script (what does it actually compute?) ===
#!/usr/bin/env python3
"""Exact finite verification for the h_170 proof-system countermodel.

The four-variable polymatroid h_170 violates candidate Q36.  This program checks
with integer arithmetic that it satisfies:
  * every elemental Shannon inequality;
  * every tuple substitution of the Zhang--Yeung inequality; and
  * every tuple substitution, for every integer k>=1, of Csirmaz Theorem 11
    (arXiv:2607.16773).

A tuple substitution maps each formal theorem variable independently to any of
the 16 subsets of {A,B,C,D}; overlap and the empty tuple are included.  The
infinite k-range is minimized exactly as a quadratic over the positive integers.
"""
from __future__ import annotations

import json
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
OUT = HERE / "h170_stability_family_no_go.json"
DEN = 170
H = np.array(
    [0, 102, 68, 170, 119, 143, 146, 170, 101, 143, 128, 170, 146, 170, 170, 170],
    dtype=np.int64,
)
Q36 = np.array([0, 0, 0, -1, -3, 2, 2, 0, -2, 1, 2, 0, 4, -2, -3, 0], dtype=np.int64)
# Q36 above includes the zero coordinate for the empty set.


def mi(x: int, y: int) -> int:
    return int(H[x] + H[y] - H[x | y])


def cmi(x: int, y: int, z: int) -> int:
    return int(H[x | z] + H[y | z] - H[z] - H[x | y | z])


def ing(x: int, y: int, a: int, b: int) -> int:
    return cmi(x, y, a) + cmi(x, y, b) + mi(a, b) - mi(x, y)


def symmetric_defect(x: int, y: int, z: int) -> int:
    return cmi(x, z, y) + cmi(y, z, x)


def elemental_shannon_slacks() -> list[int]:
    full = 15
    out: list[int] = []
    for i in range(4):
        bit = 1 << i
        out.append(int(H[full] - H[full ^ bit]))
    for i in range(4):
        for j in range(i + 1, 4):
            rest = full ^ (1 << i) ^ (1 << j)
            z = rest
            while True:
                out.append(cmi(1 << i, 1 << j, z))

