from __future__ import annotations

from dataclasses import fields
from pathlib import Path
import json

from qltc import (
    TesterSolution,
    complete_graph_check_product,
    cycle_check_product,
    cyclic_matrix,
    quantum_hamming_code,
    reed_muller_15_code,
    steane_code,
    toric_code,
    verify_solution,
)

ROOT = Path(__file__).resolve().parents[1]
CERTS = ROOT / "results" / "certificates"


def load_solution(path: Path) -> TesterSolution:
    data = json.loads(path.read_text())
    names = {f.name for f in fields(TesterSolution)}
    return TesterSolution(**{k: v for k, v in data.items() if k in names})


def resolve(name: str):
    if name.startswith("steane"):
        return steane_code()
    if name.startswith("quantum_hamming_m4"):
        return quantum_hamming_code(4)
    if name.startswith("check_product_cycle_5"):
        return cycle_check_product(5)
    if name.startswith("check_product_K5"):
        return complete_graph_check_product(5)
    if name.startswith("quantum_reed_muller"):
        return reed_muller_15_code()[0]
    if name.startswith("toric_L"):
        L = int(name.split("toric_L", 1)[1].split("_", 1)[0])
        return toric_code(L)
    if name.startswith("cyclic_n"):
        body = name.split("cyclic_n", 1)[1]
        n_text, mask_text = body.split("_mask", 1)
        n = int(n_text)
        mask = int(mask_text)
        h = cyclic_matrix(mask, n)
        from qltc.codes import CSSCode
        return CSSCode(name, h, h, {"mask": mask})
    raise KeyError(name)


def main() -> None:
    failures = []
    for path in sorted(CERTS.glob("*.json")):
        stem = path.stem
        # Certificate names are <code>_<side>_w<cap>.
        code_name, suffix = stem.rsplit("_", 2)[0], stem.rsplit("_", 2)[1:]
        side = suffix[0]
        code = resolve(code_name)
        h = code.hx if side == "X" else code.hz
        result = verify_solution(h, load_solution(path))
        print(path.name, result)
        if not result["matches"]:
            failures.append(path.name)
    if failures:
        raise SystemExit(f"certificate failures: {failures}")


if __name__ == "__main__":
    main()

